// dnsProviderName is how a DNS provider id reads on screen.
func dnsProviderName(id string) string {
	switch id {
	case "cloudflare":
		return "Cloudflare"
	case "route53":
		return "Route 53 (AWS)"
	case "digitalocean":
		return "DigitalOcean"
	case "googleclouddns":
		return "Google Cloud DNS"
	}
	return id
}

